package app.morphe.patches.example

import app.morphe.patcher.annotation.Patch
import app.morphe.patcher.patch.BytecodePatch
import app.morphe.patcher.fingerprint.Fingerprint

/**
 * Sample patch generated by Morphy Patches Creator.
 *
 * Demonstrates:
 * 1. Resilient opcode & string fingerprinting (surviving R8/ProGuard obfuscation).
 * 2. In-place method replacement targeting the Morphe Patcher runtime.
 */
@Patch(
    name = "Sample Premium Unlock",
    description = "Unlocks premium functionality by hooking local entitlement checks.",
    version = "1.0.0"
)
object SampleUnlockPatch : BytecodePatch(
    fingerprints = setOf(EntitlementCheckFingerprint)
) {
    // Fingerprint synthesized via Morphe-AI
    object EntitlementCheckFingerprint : Fingerprint(
        strings = listOf("user_is_subscribed", "entitlement_active"),
        opcodes = listOf("invoke-virtual", "move-result", "if-eqz", "return")
    )

    override fun execute() {
        EntitlementCheckFingerprint.result?.let { match ->
            // In-place Smali method body override
            match.method.replaceMethod {
                instructions = """
                    const/4 v0, 0x1
                    return v0
                """.trimIndent()
            }
        }
    }
}
